# WRF Extreme Rainfall - 3 sub-layers served from COG files

# Heavy Rainfall (90th percentile)
LAYER
    NAME "wrf_extreme_heavy"
    TYPE RASTER
    STATUS ON
    DATA "/opt/cogs/wrf-extreme-rainfall/%time%/wrf_extreme_f90.tif"
    MASK "gha_admin_extent_mask"
    PROCESSING "NODATA=0"
    PROJECTION
        "init=epsg:4326"
    END
    CLASS
        NAME "Heavy Rainfall"
        EXPRESSION ([pixel] > 0)
        STYLE
            COLOR 175 238 238
        END
    END
    METADATA
        "wms_title" "WRF Heavy Rainfall (90th percentile)"
        INCLUDE "shared/wms-layer-metadata.map"
    END
    VALIDATION
        "time" "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"
        "default_time" "2026-03-31"
    END
END

